package main

import (
	"context"
	"flag"
	"os"
	"os/signal"
	"strings"
	"time"

	"github.com/maoxiaoyue/hypgo/pkg/logger"

	"legagent/app/models"
	"legagent/app/services"
	"legagent/internal/moj"
)

// runIngest 下載全國法規資料庫公開資料，建立 data/laws JSON 與議事規則向量索引。
//
//	go run . ingest                              # 下載（含快取）→ 解析 → 索引
//	go run . ingest -reindex -reset              # 只用 data/laws/*.json 重建索引
//	go run . ingest -xml a.xml,b.xml             # 使用本地 XML
//	go run . ingest -query "法律案連署人數"       # 建完後試查
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 資料建置與伺服器分開執行，伺服器啟動時不做網路下載
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 網路下載、寫入 data/laws 與向量庫、失敗時 os.Exit
func runIngest(args []string) {
	fs := flag.NewFlagSet("ingest", flag.ExitOnError)
	var (
		cfgPath = fs.String("config", defaultConfigPath, "config.yaml 路徑")
		xmls    = fs.String("xml", "", "逗號分隔之本地 XML 路徑；留空則自官方下載（含快取）")
		reindex = fs.Bool("reindex", false, "不下載，只用 data_dir 內 JSON 重建索引")
		reset   = fs.Bool("reset", false, "先清空向量集合")
		query   = fs.String("query", "", "建置完成後執行一次試查")
		topK    = fs.Int("top_k", 3, "試查回傳筆數")
	)
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	svc, store := mustOpenRules(cfg, log)

	var (
		stats *models.IngestStats
		err   error
	)
	if *reindex {
		stats, err = svc.Reindex(ctx, *reset)
	} else {
		paths, perr := resolveXML(ctx, *xmls, cfg, log)
		if perr != nil {
			log.Error("resolve xml failed", "err", perr)
			os.Exit(1)
		}
		filter := moj.Filter{
			CategoryPrefixes: cfg.Rules.CategoryPrefixes,
			Names:            cfg.Rules.Names,
			ExcludeRepealed:  cfg.Rules.ExcludeRepealed,
		}
		stats, err = svc.IngestXML(ctx, paths, filter, *reset)
	}
	if err != nil {
		log.Error("ingest failed", "err", err)
		os.Exit(1)
	}
	log.Info("ingest done", "laws", stats.Laws, "articles", stats.Articles, "chunks", stats.Chunks, "embedder", stats.Embedder, "indexed_total", store.Count())

	if *query != "" {
		resp, err := svc.Search(ctx, models.SearchRulesReq{Query: *query, TopK: *topK})
		if err != nil {
			log.Error("query failed", "err", err)
			os.Exit(1)
		}
		for i, h := range resp.Hits {
			log.Info("hit", "rank", i+1, "score", h.Score, "law", h.LawName, "article", h.Label, "chapter", h.Chapter, "url", h.SourceURL)
			log.Info("content", "text", h.Content)
		}
	}
}

// resolveXML 回傳要解析的 XML 路徑：使用者指定的本地檔，或自官方下載（快取於 cache_dir）。
func resolveXML(ctx context.Context, flagXML string, cfg *appConfig, log *logger.Logger) ([]string, error) {
	if flagXML != "" {
		var out []string
		for _, p := range strings.Split(flagXML, ",") {
			if p = strings.TrimSpace(p); p != "" {
				out = append(out, p)
			}
		}
		return out, nil
	}
	maxAge := time.Duration(cfg.Rules.CacheMaxAgeHours) * time.Hour
	var out []string
	for _, ds := range []moj.Dataset{moj.DatasetLaws, moj.DatasetOrders} {
		log.Info("fetching dataset", "name", ds.Name, "url", ds.URL, "cache_dir", cfg.Rules.CacheDir)
		p, err := moj.Download(ctx, ds, cfg.Rules.CacheDir, maxAge)
		if err != nil {
			return nil, services.ErrRulesSourceUnavailable.With("dataset", ds.Name).With("reason", err.Error())
		}
		out = append(out, p)
	}
	return out, nil
}
